import { renderCodeHiliteBlock, renderFencedCodeBlock } from './highlight.mjs';
import { renderInline } from './inline.mjs';
import { createSlugger } from './slug.mjs';

const BLOCK_TAGS = new Set([
  'address',
  'article',
  'aside',
  'blockquote',
  'body',
  'caption',
  'dd',
  'details',
  'div',
  'dl',
  'dt',
  'fieldset',
  'figcaption',
  'figure',
  'footer',
  'form',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'header',
  'hr',
  'html',
  'li',
  'main',
  'nav',
  'ol',
  'p',
  'pre',
  'section',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'tr',
  'ul',
]);

function normalizeLineEndings(text) {
  let result = '';

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];

    if (char === '\r') {
      if (index + 1 < text.length && text[index + 1] === '\n') {
        index += 1;
      }

      result += '\n';
    } else {
      result += char;
    }
  }

  return result;
}

function splitLines(text) {
  const lines = [];
  let current = '';

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];

    if (char === '\n') {
      lines.push(current);
      current = '';
    } else {
      current += char;
    }
  }

  lines.push(current);
  return lines;
}

function isBlank(line) {
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];

    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }

  return true;
}

function isAsciiLetter(char) {
  const code = char.charCodeAt(0);
  return (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

function isDigit(char) {
  const code = char.charCodeAt(0);
  return code >= 48 && code <= 57;
}

function toLowerAscii(text) {
  let result = '';

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    const code = char.charCodeAt(0);

    if (code >= 65 && code <= 90) {
      result += String.fromCharCode(code + 32);
    } else {
      result += char;
    }
  }

  return result;
}

function trimHashes(text) {
  let end = text.length;

  while (end > 0 && text[end - 1] === '#') {
    end -= 1;
  }

  if (end < text.length) {
    let preceding = end - 1;

    while (preceding >= 0 && (text[preceding] === ' ' || text[preceding] === '\t')) {
      preceding -= 1;
    }

    if (preceding < end - 1) {
      return text.slice(0, preceding + 1);
    }
  }

  return text;
}

function parseHeading(line) {
  let index = 0;

  while (index < line.length && line[index] === ' ' && index < 4) {
    index += 1;
  }

  let level = 0;

  while (index + level < line.length && line[index + level] === '#' && level < 6) {
    level += 1;
  }

  if (level === 0 || level > 6) {
    return null;
  }

  const next = index + level;

  if (next < line.length && line[next] !== ' ' && line[next] !== '\t') {
    return null;
  }

  let content = line.slice(next).trim();
  content = trimHashes(content);

  return {
    level,
    content,
  };
