function parseListMarker(line) {
  let index = 0;

  while (index < line.length && line[index] === ' ' && index < 4) {
    index += 1;
  }

  if (index >= line.length) {
    return null;
  }

  const bullet = line[index];

  if ((bullet === '-' || bullet === '+' || bullet === '*') && index + 1 < line.length && line[index + 1] === ' ') {
    return {
      ordered: false,
      content: line.slice(index + 2),
    };
  }

  if (!isDigit(bullet)) {
    return null;
  }

  let end = index + 1;

  while (end < line.length && isDigit(line[end])) {
    end += 1;
  }

  if (end >= line.length || line[end] !== '.' || end + 1 >= line.length || line[end + 1] !== ' ') {
    return null;
  }

  return {
    ordered: true,
    content: line.slice(end + 2),
