function parseFence(line) {
  let index = 0;

  while (index < line.length && line[index] === ' ' && index < 4) {
    index += 1;
  }

  if (index >= line.length) {
    return null;
  }

  const marker = line[index];

  if (marker !== '`' && marker !== '~') {
    return null;
  }

  let count = 0;

  while (index + count < line.length && line[index + count] === marker) {
    count += 1;
  }

