  while (index + count < line.length && line[index + count] === fence.marker) {
    count += 1;
  }

  if (count < fence.count) {
    return false;
  }

  for (let check = index + count; check < line.length; check += 1) {
    const char = line[check];

    if (char !== ' ' && char !== '\t') {
