function getProgramName(scriptPath) {
  let lastSlash = -1;

  for (let index = 0; index < scriptPath.length; index += 1) {
    if (scriptPath[index] === '/' || scriptPath[index] === '\\') {
      lastSlash = index;
    }
  }

  return lastSlash === -1 ? scriptPath : scriptPath.slice(lastSlash + 1);
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

export function formatHelp(scriptPath) {
  const programName = getProgramName(scriptPath);

  return [
    usage(programName),
    '',
    'Markdown with extension configuration',
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
  ].join('\n');
}

function formatError(scriptPath, message) {
  const programName = getProgramName(scriptPath);
  return `${usage(programName)}\n${programName}: error: ${message}\n`;
}

export function parseArguments(argv, scriptPath) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };

  const unrecognized = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        message: `${formatHelp(scriptPath)}\n`,
      };
    }

    if (token === '--') {
      for (let rest = index + 1; rest < argv.length; rest += 1) {
        unrecognized.push(argv[rest]);
      }
      break;
    }

    if (token.startsWith('--a=')) {
      values.a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      values.b = token.slice(4);
      continue;
    }

    if (token.startsWith('--c=')) {
      values.c = token.slice(4);
      continue;
    }

    if (token === '--a' || token === '--b' || token === '--c') {
      if (index + 1 >= argv.length || argv[index + 1].startsWith('-')) {
        return {
          kind: 'error',
          code: 2,
          message: formatError(scriptPath, `argument ${token}: expected one argument`),
        };
      }

      const name = token.slice(2);
      values[name] = argv[index + 1];
      index += 1;
      continue;
    }

    unrecognized.push(token);
  }

  if (unrecognized.length > 0) {
    return {
      kind: 'error',
      code: 2,
      message: formatError(scriptPath, `unrecognized arguments: ${unrecognized.join(' ')}`),
    };
  }

  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  if (values.c === undefined) {
    missing.push('--c');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      code: 2,
      message: formatError(scriptPath, `the following arguments are required: ${missing.join(', ')}`),
    };
  }

  return {
    kind: 'ok',
    values,
  };
}

